INSERT INTO faq (question, answer, is_public, created_at, updated_at) VALUES
                                                                          (
                                                                              '회원탈퇴는 어떻게 하나요?',
                                                                              '회원탈퇴는 로그인 후 가능합니다.\n\n[PC] 메인홈페이지 > 이름 > 회원정보관리 > 우측하단 [회원탈퇴]\n[모바일] 메인 > 개인 홈 > 이름 > 하단 [회원탈퇴]\n\n※ 주의: 소셜회원(네이버, 카카오 등)은 해당 사이트 연결이 함께 해제되지 않을 수 있습니다.',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '회원탈퇴를 한 후 재가입은 가능한가요?',
                                                                              '탈퇴 후 60일 이내 재가입은 불가능합니다.\n\n※ 주의사항\n1. 등록한 이력서 및 지원 내역 모두 삭제 (복구 불가)\n2. 잔여 유료 크레딧 환불 불가 (탈퇴 전 문의 필수)\n3. 탈퇴 후 2~3일간 메일이 수신될 수 있습니다.',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '개인정보(주소, 메일, 전화번호 등) 변경은 어디서 하나요?',
                                                                              '로그인 후 [회원정보관리] 또는 [이력서 수정] 페이지에서 변경 가능합니다.\n\n- 이름, 생년월일: 회원정보관리\n- 휴대폰, 이메일, 주소: 회원정보관리 및 이력서\n\n변경된 정보는 지원한 기업의 연락처로 사용되므로 최신화를 권장합니다.',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '아이디와 비밀번호를 잊어버렸어요.',
                                                                              '[아이디 찾기] 본인 확인 후 아이디 일부 확인 가능.\n[비밀번호 찾기] 가입한 이메일/휴대폰으로 임시 비밀번호 발송.\n\n정보가 변경되어 수신이 불가능한 경우 고객센터로 문의 바랍니다.',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '공고 등록 비용은 얼마이고, 몇 개까지 가능한가요?',
                                                                              '공고 등록은 기본적으로 무료이나, 상단 노출 등 프리미엄 기능은 유료 크레딧을 사용합니다. 등록 개수 제한은 기업 회원 등급에 따라 상이할 수 있습니다.',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '공고 등록 방법이 궁금합니다.',
                                                                              '1. 공고명: 직무명 위주 입력 (임의 수정될 수 있음)\n2. 직군/직무: 최대 3개 선택\n3. 경력: 신입(0~1년)과 경력 분리 등록 권장\n4. 근무지: 지도 표시용 주소 입력\n5. 마감일: 상시 또는 직접 설정\n6. 알림 이메일: 지원자 발생 시 알림 받을 주소',
                                                                              true, now(), now()
                                                                          ),
                                                                          (
                                                                              '광고를 집행하고 싶습니다. 절차가 어떻게 되나요?',
